message.content:
{
  "gate_token": "IlCdXa4-dO2p1LKR2Em4fA",
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unfolds a map of the ruined royal city.",
      "visual_description": "A windswept hill overlooks a shattered skyline of broken spires; Mara crouches with a parchment map weighted by her brass compass.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of obvious traps ahead.",
      "visual_description": "A single-eyed flame flickers inside a battered oil lamp, projecting warning shapes onto Mara's map at dusk.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The tin fox scouts the cracked castle gates.",
      "visual_description": "A small clockwork fox with blue glass eyes peers through a tilted iron gate carved with faded royal crests.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Glass diver arrives by stepping out of a broken window.",
      "visual_description": "A figure in a clear diving helmet emerges from a shattered shopfront window, coat catching reflections of distant fires.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "The team ignores rumors of a beast on the cursed tower.",
      "visual_description": "A leaning black tower spews green smoke against a bruised sky while the team passes below, eyes fixed forward.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "Tattered royal banners snag at their coats.",
      "visual_description": "Faded crimson banners hang from broken poles, brushing the ink-stained coat of Mara as she pushes through a narrow alley.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "Frightened townsfolk hide their faces in doorways.",
      "visual_description": "Pale faces peek from shuttered windows above as the tin fox trots past lanterns flickering in a rain-slicked street.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "Armored patrols march in clanking formation.",
      "visual_description": "From a high balcony, Mara and the glass diver crouch behind a stone gargoyle while plumed helmets pass below in torchlight.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "The sleeping tax collector blocks the records hall.",
      "visual_description": "A round official snores at a desk piled with ledgers, stamped papers stuck to his sleeves and drool pooling on a seal.",
      "characters": ["sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "The oracle lamp deciphers a sealed magic door.",
      "visual_description": "Glowing runes ripple along an arched iron door as the lamp's single eye beams a thin line of light across the symbols.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "Glass diver slips through a tall mirror.",
      "visual_description": "The rescuer dives forward and ripples into a full-length mirror like water, helmet catching candlelight on the other side.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Inside the mirror-world, the lost captive waits.",
      "visual_description": "A small reflected chamber holds the sleeping tax collector slumped in chains of paperwork, ledger pillow beneath his head.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 13,
      "caption": "Tin fox chews through the paper bindings.",
      "visual_description": "The clockwork fox's brass jaws shred ribbons of stamped documents while its key-wind tail spins in concentration.",
      "characters": ["tin_fox", "sleeping_tax_collector", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "The oracle lamp shouts that the patrols return.",
      "visual_description": "The lamp's eye flares red, throwing harsh shadows across Mara's worried face in a corridor of cracked marble.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 15,
      "caption": "Mara charts a hidden route to the river.",
      "visual_description": "Her brass compass spins wildly over the map, then settles, pointing toward a narrow alley sketched in fresh ink.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "They emerge from a fountain into open night air.",
      "visual_description": "The glass diver rises out of a moonlit fountain carrying the still-snoring official, water sheeting off his coat.",
      "characters": ["glass_diver", "sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 17,
      "caption": "The team sprints across a crumbling bridge.",
      "visual_description": "A long stone bridge arches over a black river; lanterns swing as the four companions race past fallen statues toward the far bank.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far shore, the lamp winks once.",
      "visual_description": "On a grassy ridge beyond the river, the rescued official finally stirs while the oracle lamp's eye dims to a contented ember.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

